"""Regular-language objects for the documented ``match`` predicate.

Grammar (the only dialect the profile supports):

    union    := sequence ( '|' sequence )*
    sequence := atom*
    atom     := primary '*'*
    primary  := literal | '(' union ')' | '[' items ']'

A backslash escapes the next character both inside and outside a class.
Outside a class the unescaped characters ``()[]|*\\`` are grammar symbols;
inside a class only ``-``, ``]`` and ``\\`` are special, so every other
character - including ``.`` - is a literal.  There are no anchors, no dot
wildcard, no ``+``/``?``, no negated classes, and no numeric escapes.

Matching is a full byte-string membership test over Latin-1 code points, so a
code point outside every ASCII range in the pattern simply fails.  Repetition
of nullable expressions is supported, which is why the engine is an epsilon
NFA simulation rather than a backtracker.
"""

from typing import List, Optional, Tuple


class Regex(object):
    """A regular expression."""

    __slots__ = ()

    def nullable(self) -> bool:
        raise NotImplementedError(type(self).__name__)


class Empty(Regex):
    """A regular expression that matches the empty string."""

    __slots__ = ()

    def nullable(self) -> bool:
        return True

    def __str__(self) -> str:
        return ""


class Range(Regex):
    """A regular expression that matches one character in an inclusive range."""

    __slots__ = ("low", "high")

    def __init__(self, low: str, high: str):
        if len(low) != 1 or len(high) != 1:
            raise ValueError("Range must be single characters")
        self.low = low
        self.high = high

    def nullable(self) -> bool:
        return False

    def __str__(self) -> str:
        return "[%s-%s]" % (self.low, self.high)


class Choice(Regex):
    """A regular expression that matches one of several expressions."""

    __slots__ = ("exprs",)

    def __init__(self, *args: List[Regex]):
        if len(args) < 2:
            raise ValueError("Choice must have at least two expressions")
        self.exprs = args

    def nullable(self) -> bool:
        return any(e.nullable() for e in self.exprs)

    def __str__(self) -> str:
        return "(" + "|".join(str(e) for e in self.exprs) + ")"


class Seq(Regex):
    """A regular expression that matches a sequence of expressions."""

    __slots__ = ("exprs",)

    def __init__(self, *args: List[Regex]):
        if len(args) < 2:
            raise ValueError("Seq must have at least two expressions")
        self.exprs = args

    def nullable(self) -> bool:
        return all(e.nullable() for e in self.exprs)

    def __str__(self) -> str:
        return "(" + "".join(str(e) for e in self.exprs) + ")"


class Star(Regex):
    """A regular expression that matches zero or more iterations."""

    __slots__ = ("expr",)

    def __init__(self, r: Regex):
        self.expr = r

    def nullable(self) -> bool:
        return True

    def __str__(self) -> str:
        return "(" + str(self.expr) + ")*"


def chars(low: str, high: str) -> Regex:
    """A regular expression that matches a character range."""
    if low == high:
        return Range(low, high)
    return Range(low, high)


def text(s: str) -> Regex:
    """A regular expression that matches an exact string."""
    if s == "":
        return empty()
    if len(s) == 1:
        return chars(s, s)
    return seq(*[chars(c, c) for c in s])


def choice(*args: List[Regex]) -> Regex:
    """A regular expression that matches a choice of expressions."""
    if len(args) == 1:
        return args[0]
    return Choice(*args)


def seq(*args: List[Regex]) -> Regex:
    """A regular expression that matches a sequence of expressions."""
    if len(args) == 1:
        return args[0]
    return Seq(*args)


def star(r: Regex) -> Regex:
    """A regular expression that matches zero or more iterations."""
    return Star(r)


def empty() -> Regex:
    """A regular expression that matches the empty string."""
    return Empty()


# --------------------------------------------------------------------------- #
# Parser
# --------------------------------------------------------------------------- #

_GRAMMAR = "()[]|*\\"


def _char(source: str, i: int) -> Tuple[str, int]:
    """Read one atom character outside a class, honouring escapes."""
    ch = source[i]
    if ch == "\\":
        if i + 1 < len(source):
            return source[i + 1], i + 2
        return "\\", i + 1
    return ch, i + 1


def _class_char(source: str, i: int) -> Tuple[str, int]:
    """Read one class item character, honouring escapes."""
    ch = source[i]
    if ch == "\\":
        if i + 1 < len(source):
            return source[i + 1], i + 2
        return "\\", i + 1
    return ch, i + 1


def _class(source: str, i: int) -> Tuple[Regex, int]:
    """Parse ``[items]`` starting at the opening bracket."""
    i += 1
    n = len(source)
    items = []
    while i < n and source[i] != "]":
        low, i = _class_char(source, i)
        if i + 1 < n and source[i] == "-" and source[i + 1] != "]":
            high, i = _class_char(source, i + 1)
            items.append(Range(low, high))
        else:
            items.append(Range(low, low))
    if i < n:
        i += 1  # closing bracket
    if not items:
        return Empty(), i
    if len(items) == 1:
        return items[0], i
    return Choice(*items), i


def _primary(source: str, i: int) -> Tuple[Regex, int]:
    ch = source[i]
    if ch == "(":
        inner, j = _union(source, i + 1)
        if j < len(source) and source[j] == ")":
            j += 1
        return inner, j
    if ch == "[":
        return _class(source, i)
    if ch == "\\":
        if i + 1 < len(source):
            return Range(source[i + 1], source[i + 1]), i + 2
        return Range("\\", "\\"), i + 1
    if ch in _GRAMMAR:
        # Stray grammar symbol: the documented grammar never produces one, but
        # treat it as a literal instead of failing the whole campaign.
        return Range(ch, ch), i + 1
    return Range(ch, ch), i + 1


def _atom(source: str, i: int) -> Tuple[Regex, int]:
    node, i = _primary(source, i)
    while i < len(source) and source[i] == "*":
        node = Star(node)
        i += 1
    return node, i


def _sequence(source: str, i: int) -> Tuple[Regex, int]:
    atoms = []
    n = len(source)
    while i < n:
        ch = source[i]
        if ch == "|" or ch == ")":
            break
        if ch == "*":
            # A repetition marker with no preceding atom matches only the empty
            # string; consume it rather than looping forever.
            i += 1
            continue
        node, i = _atom(source, i)
        atoms.append(node)
    if not atoms:
        return Empty(), i
    if len(atoms) == 1:
        return atoms[0], i
    return Seq(*atoms), i


def _union(source: str, i: int) -> Tuple[Regex, int]:
    alternatives = []
    n = len(source)
    while True:
        node, i = _sequence(source, i)
        alternatives.append(node)
        if i < n and source[i] == "|":
            i += 1
            continue
        break
    if len(alternatives) == 1:
        return alternatives[0], i
    return Choice(*alternatives), i


def parse(source: str) -> Regex:
    """Parse one documented pattern into a regular-language object."""
    if source == "":
        return Empty()
    node, _ = _union(source, 0)
    return node


# --------------------------------------------------------------------------- #
# Epsilon NFA engine
# --------------------------------------------------------------------------- #

class Pattern(object):
    """A compiled pattern: an epsilon NFA plus per-code-point move tables."""

    __slots__ = ("source", "regex", "moves", "eps", "closure", "start", "accept", "delta", "nullable")

    def __init__(self, source: str, regex: Regex):
        moves: List[Optional[Tuple[Tuple[Tuple[int, int], ...], int]]] = []
        eps: List[List[int]] = []

        def new():
            moves.append(None)
            eps.append([])
            return len(moves) - 1

        def link(a, b):
            eps[a].append(b)

        def build(node):
            kind = type(node)
            if kind is Empty:
                s, a = new(), new()
                link(s, a)
                return s, a
            if kind is Range:
                s, a = new(), new()
                low, high = ord(node.low), ord(node.high)
                moves[s] = (((low, high),), a)
                return s, a
            if kind is Choice:
                s, a = new(), new()
                for part in node.exprs:
                    ss, sa = build(part)
                    link(s, ss)
                    link(sa, a)
                return s, a
            if kind is Seq:
                s, a = new(), new()
                current = s
                for part in node.exprs:
                    ss, sa = build(part)
                    link(current, ss)
                    current = sa
                link(current, a)
                return s, a
            if kind is Star:
                s, a = new(), new()
                ss, sa = build(node.expr)
                link(s, ss)
                link(s, a)
                link(sa, ss)
                link(sa, a)
                return s, a
            raise ValueError("unknown regex node")

        start, accept = build(regex)
        self.source = source
        self.regex = regex
        self.moves = tuple(moves)
        self.eps = tuple(tuple(e) for e in eps)
        self.start = start
        self.accept = accept
        self.nullable = regex.nullable()
        # epsilon closure of every single state (always includes itself)
        closure = []
        for state in range(len(self.moves)):
            seen = set()
            stack = [state]
            while stack:
                current = stack.pop()
                if current in seen:
                    continue
                seen.add(current)
                stack.extend(self.eps[current])
            closure.append(frozenset(seen))
        self.closure = tuple(closure)
        self.delta = {}

    def _delta_for(self, code: int):
        table = self.delta.get(code)
        if table is None:
            table = {}
            for state, entry in enumerate(self.moves):
                if entry is None:
                    continue
                ranges, target = entry
                for low, high in ranges:
                    if low <= code <= high:
                        table[state] = target
                        break
            self.delta[code] = table
        return table

    def matches(self, value: str) -> bool:
        """Full membership test over the Latin-1 code points of ``value``."""
        closure = self.closure
        current = closure[self.start]
        accept = self.accept
        for ch in value:
            table = self._delta_for(ord(ch))
            if not table:
                return False
            nxt = None
            for state in current:
                target = table.get(state)
                if target is not None:
                    if nxt is None:
                        nxt = set(closure[target])
                    else:
                        nxt.update(closure[target])
            if nxt is None:
                return False
            if accept in nxt:
                current = frozenset(nxt)
            else:
                current = nxt
            if not current:
                return False
        return accept in current


_CACHE = {}


def compile(source: str) -> Pattern:
    """Compile (and memoize) one pattern source into a reusable matcher."""
    pattern = _CACHE.get(source)
    if pattern is None:
        pattern = Pattern(source, parse(source))
        _CACHE[source] = pattern
    return pattern


def ismatch(r, s: str) -> bool:
    """Determine if a string fully matches a regular expression."""
    if isinstance(r, Pattern):
        return r.matches(s)
    return Pattern("", r).matches(s)
